/* ═══ ZMensch (v813): 3D-Figur „Mensch“ (Quaternius, CC0) als Skin – GLB eingebettet, kleiner eigener GLB-Leser ═══ */
(function(){
  if(window.ZMensch) return;
  const B64='';
  let cache=null;
  function parse(){
    const bin=atob(B64), u8=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++) u8[i]=bin.charCodeAt(i);
    const dv=new DataView(u8.buffer); const jl=dv.getUint32(12,true); const J=JSON.parse(new TextDecoder().decode(u8.subarray(20,20+jl)));
    const bo=20+jl+8; const bufU8=u8.subarray(bo);
    const acc=i=>{ const a=J.accessors[i], v=J.bufferViews[a.bufferView], off=(v.byteOffset||0)+(a.byteOffset||0), n=a.count*({SCALAR:1,VEC2:2,VEC3:3}[a.type]);
      const ab=bufU8.buffer.slice(bufU8.byteOffset+off,bufU8.byteOffset+off+n*(a.componentType===5123?2:4)); return a.componentType===5123?new Uint16Array(ab):new Float32Array(ab); };
    const geos=J.meshes[0].primitives.map(p=>{ const g=new THREE.BufferGeometry(); g.setAttribute('position',new THREE.BufferAttribute(acc(p.attributes.POSITION),3)); g.setAttribute('normal',new THREE.BufferAttribute(acc(p.attributes.NORMAL),3)); g.setIndex(new THREE.BufferAttribute(acc(p.indices),1)); return {g,m:J.materials[p.material].pbrMetallicRoughness.baseColorFactor}; });
    return geos; }
  window.ZMensch={ H:1.9,
    build(){ if(!cache) cache=parse(); const grp=new THREE.Group(); const minY=1.2421486, hh=3.7643564-minY, s=window.ZMensch.H/hh;
      cache.forEach(o=>{ const c=o.m, col=new THREE.Color().setRGB(Math.pow(c[0],1/2.2),Math.pow(c[1],1/2.2),Math.pow(c[2],1/2.2)); const mesh=new THREE.Mesh(o.g,new THREE.MeshLambertMaterial({color:col,side:THREE.DoubleSide})); grp.add(mesh); });
      grp.scale.setScalar(s); grp.position.y=-minY*s; return grp; } };
})();
